//! The app-owned shadcn Neutral theme for gpuicn.
//!
//! Source: shadcn/ui 4.19.0 at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`, Nova style.

use gpui::{App, Global, Pixels, Rgba, SharedString, px};

/// The active color mode.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ThemeMode {
    /// The Neutral light palette.
    Light,
    /// The Neutral dark palette.
    Dark,
}

/// Semantic colors consumed by installed components.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiColors {
    /// App background.
    pub background: Rgba,
    /// Default foreground.
    pub foreground: Rgba,
    /// Card background.
    pub card: Rgba,
    /// Card foreground.
    pub card_foreground: Rgba,
    /// Popover background.
    pub popover: Rgba,
    /// Popover foreground.
    pub popover_foreground: Rgba,
    /// Primary control background.
    pub primary: Rgba,
    /// Primary control foreground.
    pub primary_foreground: Rgba,
    /// Secondary control background.
    pub secondary: Rgba,
    /// Secondary control foreground.
    pub secondary_foreground: Rgba,
    /// Muted background.
    pub muted: Rgba,
    /// Muted foreground.
    pub muted_foreground: Rgba,
    /// Accent background.
    pub accent: Rgba,
    /// Accent foreground.
    pub accent_foreground: Rgba,
    /// Destructive action color.
    pub destructive: Rgba,
    /// Default border.
    pub border: Rgba,
    /// Input border.
    pub input: Rgba,
    /// Focus ring.
    pub ring: Rgba,
    /// First chart color.
    pub chart_1: Rgba,
    /// Second chart color.
    pub chart_2: Rgba,
    /// Third chart color.
    pub chart_3: Rgba,
    /// Fourth chart color.
    pub chart_4: Rgba,
    /// Fifth chart color.
    pub chart_5: Rgba,
    /// Sidebar background.
    pub sidebar: Rgba,
    /// Sidebar foreground.
    pub sidebar_foreground: Rgba,
    /// Sidebar primary background.
    pub sidebar_primary: Rgba,
    /// Sidebar primary foreground.
    pub sidebar_primary_foreground: Rgba,
    /// Sidebar accent background.
    pub sidebar_accent: Rgba,
    /// Sidebar accent foreground.
    pub sidebar_accent_foreground: Rgba,
    /// Sidebar border.
    pub sidebar_border: Rgba,
    /// Sidebar focus ring.
    pub sidebar_ring: Rgba,
}

/// Theme font family names. Applications own font loading.
#[derive(Clone, Debug, PartialEq)]
pub struct UiFonts {
    /// Default body family.
    pub body: SharedString,
    /// Default heading family.
    pub heading: SharedString,
    /// Default monospace family.
    pub mono: SharedString,
}

/// Base corner radius from the pinned shadcn theme.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiRadius {
    /// Ten pixels (`0.625rem` at the shadcn 16px root size).
    pub base: Pixels,
}

/// Base spacing unit from the pinned Nova style.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiSpacing {
    /// Four pixels.
    pub unit: Pixels,
}

/// The application-owned theme stored in GPUI global state.
#[derive(Clone, Debug, PartialEq)]
pub struct UiTheme {
    /// Active color mode.
    pub mode: ThemeMode,
    /// Active semantic colors.
    pub colors: UiColors,
    /// Font family names.
    pub fonts: UiFonts,
    /// Base corner radius.
    pub radius: UiRadius,
    /// Base spacing unit.
    pub spacing: UiSpacing,
}

impl Global for UiTheme {}

impl Default for UiTheme {
    fn default() -> Self {
        Self::neutral_light()
    }
}

impl UiTheme {
    /// Creates the pinned Neutral light theme.
    pub fn neutral_light() -> Self {
        Self::new(ThemeMode::Light, neutral_light_colors())
    }

    /// Creates the pinned Neutral dark theme.
    pub fn neutral_dark() -> Self {
        Self::new(ThemeMode::Dark, neutral_dark_colors())
    }

    /// Installs a theme into the application.
    pub fn set(cx: &mut App, theme: Self) {
        cx.set_global(theme);
    }

    /// Reads the installed theme.
    ///
    /// Panics when the application has not installed a theme.
    pub fn read(cx: &App) -> &Self {
        cx.global::<Self>()
    }

    /// Replaces the installed theme with the pinned palette for `mode`.
    pub fn switch(cx: &mut App, mode: ThemeMode) {
        Self::set(
            cx,
            match mode {
                ThemeMode::Light => Self::neutral_light(),
                ThemeMode::Dark => Self::neutral_dark(),
            },
        );
    }

    fn new(mode: ThemeMode, colors: UiColors) -> Self {
        Self {
            mode,
            colors,
            fonts: UiFonts {
                body: "Geist".into(),
                heading: "Geist".into(),
                mono: "Geist Mono".into(),
            },
            radius: UiRadius { base: px(10.) },
            spacing: UiSpacing { unit: px(4.) },
        }
    }
}

fn neutral_light_colors() -> UiColors {
    UiColors {
        background: neutral(1.0),
        foreground: neutral(0.145),
        card: neutral(1.0),
        card_foreground: neutral(0.145),
        popover: neutral(1.0),
        popover_foreground: neutral(0.145),
        primary: neutral(0.205),
        primary_foreground: neutral(0.985),
        secondary: neutral(0.97),
        secondary_foreground: neutral(0.205),
        muted: neutral(0.97),
        muted_foreground: neutral(0.556),
        accent: neutral(0.97),
        accent_foreground: neutral(0.205),
        destructive: srgb(0xdc, 0x26, 0x26),
        border: neutral(0.922),
        input: neutral(0.922),
        ring: neutral(0.708),
        chart_1: neutral(0.87),
        chart_2: neutral(0.556),
        chart_3: neutral(0.439),
        chart_4: neutral(0.371),
        chart_5: neutral(0.269),
        sidebar: neutral(0.985),
        sidebar_foreground: neutral(0.145),
        sidebar_primary: neutral(0.205),
        sidebar_primary_foreground: neutral(0.985),
        sidebar_accent: neutral(0.97),
        sidebar_accent_foreground: neutral(0.205),
        sidebar_border: neutral(0.922),
        sidebar_ring: neutral(0.708),
    }
}

fn neutral_dark_colors() -> UiColors {
    UiColors {
        background: neutral(0.145),
        foreground: neutral(0.985),
        card: neutral(0.205),
        card_foreground: neutral(0.985),
        popover: neutral(0.205),
        popover_foreground: neutral(0.985),
        primary: neutral(0.922),
        primary_foreground: neutral(0.205),
        secondary: neutral(0.269),
        secondary_foreground: neutral(0.985),
        muted: neutral(0.269),
        muted_foreground: neutral(0.708),
        accent: neutral(0.269),
        accent_foreground: neutral(0.985),
        destructive: srgb(0xff, 0x64, 0x67),
        border: neutral_alpha(1.0, 0.10),
        input: neutral_alpha(1.0, 0.15),
        ring: neutral(0.556),
        chart_1: neutral(0.87),
        chart_2: neutral(0.556),
        chart_3: neutral(0.439),
        chart_4: neutral(0.371),
        chart_5: neutral(0.269),
        sidebar: neutral(0.205),
        sidebar_foreground: neutral(0.985),
        sidebar_primary: srgb(0x14, 0x47, 0xe6),
        sidebar_primary_foreground: neutral(0.985),
        sidebar_accent: neutral(0.269),
        sidebar_accent_foreground: neutral(0.985),
        sidebar_border: neutral_alpha(1.0, 0.10),
        sidebar_ring: neutral(0.556),
    }
}

pub(super) fn neutral(l: f64) -> Rgba {
    neutral_alpha(l, 1.0)
}

fn neutral_alpha(l: f64, alpha: f64) -> Rgba {
    let channel = srgb_channel(l * l * l) as f32;

    Rgba {
        r: channel,
        g: channel,
        b: channel,
        a: alpha.clamp(0.0, 1.0) as f32,
    }
}

const fn srgb(red: u8, green: u8, blue: u8) -> Rgba {
    Rgba {
        r: red as f32 / 255.0,
        g: green as f32 / 255.0,
        b: blue as f32 / 255.0,
        a: 1.0,
    }
}

fn srgb_channel(channel: f64) -> f64 {
    if channel >= 0.003_130_8 {
        (1.055 * channel.powf(1.0 / 2.4) - 0.055).clamp(0.0, 1.0)
    } else {
        (12.92 * channel).clamp(0.0, 1.0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn converts_pinned_neutral_tokens() {
        assert_eq!(
            neutral(1.0),
            Rgba {
                r: 1.0,
                g: 1.0,
                b: 1.0,
                a: 1.0,
            }
        );
        assert_eq!(
            neutral(0.0),
            Rgba {
                r: 0.0,
                g: 0.0,
                b: 0.0,
                a: 1.0,
            }
        );

        assert_eq!(neutral_light_colors().destructive, srgb(0xdc, 0x26, 0x26));
        assert_eq!(neutral_dark_colors().destructive, srgb(0xff, 0x64, 0x67));
        assert_eq!(
            neutral_dark_colors().sidebar_primary,
            srgb(0x14, 0x47, 0xe6)
        );
    }

    #[test]
    fn preserves_pinned_alpha_tokens() {
        let dark = neutral_dark_colors();
        assert_eq!(dark.border.a, 0.10);
        assert_eq!(dark.input.a, 0.15);
        assert_eq!(dark.sidebar_border.a, 0.10);
    }
}

//! The shadcn Nova Navigation Menu visual port.
//!
//! Visual source: shadcn/ui 4.19.0 `navigation-menu.tsx` and
//! `style-nova.css` at `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`.
//! Hover delays, safe-polygon handling, keyboard navigation, and popup
//! positioning come from the pinned Base GPUI Navigation Menu primitives.

pub use base_gpui::navigation_menu::{
    NavigationMenuArrow, NavigationMenuBackdrop, NavigationMenuContent, NavigationMenuIcon,
    NavigationMenuItem, NavigationMenuLink, NavigationMenuList, NavigationMenuPopup,
    NavigationMenuPortal, NavigationMenuPositioner, NavigationMenuRoot, NavigationMenuTrigger,
    NavigationMenuViewport,
};
use gpui::{
    App, BoxShadow, FontWeight, InteractiveElement as _, ParentElement as _, Styled,
    prelude::FluentBuilder as _, px,
};
use gpui_icons::{LucideIcon, lucide};

use super::theme::UiTheme;

/// Creates a horizontal Navigation Menu root. Set an accessible label when a window has more than one navigation landmark.
pub fn navigation_menu<T: Clone + Eq + 'static>(cx: &App) -> NavigationMenuRoot<T> {
    let theme = UiTheme::read(cx).clone();
    NavigationMenuRoot::new()
        .relative()
        .flex()
        .items_center()
        .justify_center()
        .font_family(theme.fonts.body)
}

/// Creates the visible list container.
pub fn navigation_menu_list<T: Clone + Eq + 'static>() -> NavigationMenuList<T> {
    NavigationMenuList::new().flex().items_center()
}

/// Creates a positioning item container.
pub fn navigation_menu_item<T: Clone + Eq + 'static>() -> NavigationMenuItem<T> {
    NavigationMenuItem::new().relative()
}

/// Creates a Nova trigger with its rotating-chevron slot.
pub fn navigation_menu_trigger<T: Clone + Eq + 'static>(cx: &App) -> NavigationMenuTrigger<T> {
    let theme = UiTheme::read(cx).clone();
    let icon_color = theme.colors.muted_foreground;
    NavigationMenuTrigger::new()
        .style_with_state(move |state, base| {
            let colors = theme.colors;
            base.flex()
                .items_center()
                .justify_center()
                .h(px(32.0))
                .rounded(theme.radius.base)
                .border_1()
                .border_color(colors.background.alpha(0.0))
                .px(px(10.0))
                .py(px(6.0))
                .font_family(theme.fonts.body.clone())
                .font_weight(FontWeight::MEDIUM)
                .text_size(px(14.0))
                .text_color(colors.foreground)
                .when(state.open, |base| base.bg(colors.muted.alpha(0.50)))
                .when(!state.disabled, |base| {
                    base.cursor_pointer()
                        .hover(move |style| style.bg(colors.muted))
                })
                .when(state.disabled, |base| {
                    base.opacity(0.50).cursor_not_allowed()
                })
                .focus_visible(move |style| {
                    style
                        .bg(colors.muted)
                        .border_color(colors.ring)
                        .shadow(vec![
                            BoxShadow::new(px(0.0), px(0.0), colors.ring.alpha(0.50).into())
                                .spread_radius(px(3.0)),
                        ])
                })
        })
        .child(
            navigation_menu_icon(cx).child(
                lucide(LucideIcon::ChevronDown)
                    .size(px(12.0))
                    .text_color(icon_color),
            ),
        )
}

/// Creates the popup content container.
pub fn navigation_menu_content<T: Clone + Eq + 'static>(cx: &App) -> NavigationMenuContent<T> {
    let theme = UiTheme::read(cx).clone();
    NavigationMenuContent::new().style_with_state(move |_state, base| {
        base.p(px(4.0))
            .font_family(theme.fonts.body.clone())
            .text_color(theme.colors.popover_foreground)
    })
}

/// Creates the portal that hosts popup geometry outside the menu root.
pub fn navigation_menu_portal<T: Clone + Eq + 'static>() -> NavigationMenuPortal<T> {
    NavigationMenuPortal::new()
}

/// Creates a positioned popup surface.
pub fn navigation_menu_positioner<T: Clone + Eq + 'static>() -> NavigationMenuPositioner<T> {
    NavigationMenuPositioner::new()
}

/// Creates the Nova popup card.
pub fn navigation_menu_popup<T: Clone + Eq + 'static>(cx: &App) -> NavigationMenuPopup<T> {
    let theme = UiTheme::read(cx).clone();
    NavigationMenuPopup::new().style_with_state(move |_state, base| {
        base.rounded(theme.radius.base)
            .bg(theme.colors.popover)
            .text_color(theme.colors.popover_foreground)
            .shadow(vec![
                BoxShadow::new(px(0.0), px(0.0), theme.colors.foreground.alpha(0.10).into())
                    .spread_radius(px(1.0)),
            ])
    })
}

/// Creates the animated viewport inside a Navigation Menu popup.
pub fn navigation_menu_viewport<T: Clone + Eq + 'static>(cx: &App) -> NavigationMenuViewport<T> {
    let theme = UiTheme::read(cx).clone();
    NavigationMenuViewport::new().style_with_state(move |_state, base| {
        base.overflow_hidden()
            .rounded(theme.radius.base)
            .bg(theme.colors.popover)
            .text_color(theme.colors.popover_foreground)
    })
}

/// Creates a Nova navigation link.
pub fn navigation_menu_link<T: Clone + Eq + 'static>(cx: &App) -> NavigationMenuLink<T> {
    let theme = UiTheme::read(cx).clone();
    NavigationMenuLink::new().style_with_state(move |state, base| {
        let colors = theme.colors;
        base.flex()
            .items_center()
            .gap(px(8.0))
            .rounded(theme.radius.base)
            .border_1()
            .border_color(colors.popover.alpha(0.0))
            .p(px(8.0))
            .font_family(theme.fonts.body.clone())
            .text_size(px(14.0))
            .text_color(colors.popover_foreground)
            .when(state.active, |base| base.bg(colors.muted.alpha(0.50)))
            .hover(move |style| style.bg(colors.muted))
            .focus_visible(move |style| {
                style.border_color(colors.ring).shadow(vec![
                    BoxShadow::new(px(0.0), px(0.0), colors.ring.alpha(0.50).into())
                        .spread_radius(px(3.0)),
                ])
            })
    })
}

/// Creates a small chevron/icon slot that rotates with its trigger state.
pub fn navigation_menu_icon<T: Clone + Eq + 'static>(cx: &App) -> NavigationMenuIcon<T> {
    let theme = UiTheme::read(cx).clone();
    NavigationMenuIcon::new().style_with_state(move |_state, base| {
        base.ml(px(4.0))
            .size(px(12.0))
            .text_color(theme.colors.muted_foreground)
    })
}

/// Creates the optional popup arrow treatment.
pub fn navigation_menu_arrow<T: Clone + Eq + 'static>(cx: &App) -> NavigationMenuArrow<T> {
    let theme = UiTheme::read(cx).clone();
    NavigationMenuArrow::new().style_with_state(move |_state, base| {
        base.size(px(8.0)).bg(theme.colors.border).rounded(px(2.0))
    })
}

/// Creates the optional transparent backdrop, retained for outside-click dismissal.
pub fn navigation_menu_backdrop<T: Clone + Eq + 'static>() -> NavigationMenuBackdrop<T> {
    NavigationMenuBackdrop::new()
}
